// Нууц үгтэй ажиллах туслахууд. Энэ файлыг өөрчлөх шаардлагагүй.
//
// Жинхэнэ Web Crypto (PBKDF2-SHA256) ашиглаж байна. Нууц үгийг ЯМАР Ч
// тохиолдолд задгайгаар хадгалж болохгүй — зөвхөн давс (salt) ба хэш.
// Бодит систем дээр энэ хоёр функцийг өөрөө бичихгүй, argon2 эсвэл bcrypt
// сан ашигладаг (Хийе платформ өөрөө argon2id хэрэглэдэг).

const PBKDF2_ITERATIONS = 100000;

function toHex(buffer) {
  return Array.from(new Uint8Array(buffer))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

function randomSalt() {
  return toHex(crypto.getRandomValues(new Uint8Array(16)));
}

async function hashPassword(password, salt) {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"],
  );

  const bits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: new TextEncoder().encode(salt),
      iterations: PBKDF2_ITERATIONS,
      hash: "SHA-256",
    },
    key,
    256,
  );

  return toHex(bits);
}

async function verifyPassword(password, user) {
  const attempt = await hashPassword(password, user.salt);
  return attempt === user.hash;
}

// Shop.mn-ий сервер — нэвтрэлт ба эрх.

// Хариу бүрийг JSON болгож буцаах жижиг туслах.
function json(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: { "Content-Type": "application/json" },
  });
}

// Хүсэлтийн толгойгоос нэвтэрсэн хэрэглэгчийг олох.
function userFromRequest(request) {
  const header = request.headers.get("Authorization");
  if (!header || !header.startsWith("Bearer ")) return null;

  const token = header.slice("Bearer ".length);
  const userId = db.sessions[token];
  if (userId === undefined) return null;

  return db.users.find((user) => user.id === userId) || null;
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  if (path === "/api/register" && request.method === "POST") {
    const input = await request.json();

    if (!input.email || !input.password || input.password.length < 8) {
      return json({ error: "Имэйл болон 8-аас урт нууц үг шаардлагатай" }, 400);
    }

    if (db.users.some((user) => user.email === input.email)) {
      return json({ error: "Энэ имэйл бүртгэлтэй байна" }, 409);
    }

    const salt = randomSalt();
    const user = {
      id: db.users.length + 1,
      name: input.name,
      email: input.email,
      salt: salt,
      hash: await hashPassword(input.password, salt),
    };
    db.users.push(user);

    return json({ id: user.id, name: user.name, email: user.email }, 201);
  }

  if (path === "/api/login" && request.method === "POST") {
    const input = await request.json();
    const user = db.users.find((candidate) => candidate.email === input.email);

    // Имэйл буруу ч, нууц үг буруу ч ИЖИЛ хариу — аль нь буруу болохыг
    // хэлэх нь халдагчид бүртгэлтэй имэйлүүдийг олох боломж өгнө.
    if (!user || !(await verifyPassword(input.password, user))) {
      return json({ error: "Имэйл эсвэл нууц үг буруу" }, 401);
    }

    const token = crypto.randomUUID();
    db.sessions[token] = user.id;

    return json({ token: token, name: user.name });
  }

  if (path === "/api/me" && request.method === "GET") {
    const user = userFromRequest(request);
    if (!user) {
      return json({ error: "Нэвтрэх шаардлагатай" }, 401);
    }
    return json({ id: user.id, name: user.name, email: user.email });
  }

  if (path === "/api/orders" && request.method === "GET") {
    const user = userFromRequest(request);
    if (!user) {
      return json({ error: "Нэвтрэх шаардлагатай" }, 401);
    }
    return json(db.orders.filter((order) => order.userId === user.id));
  }

  const orderMatch = path.match(/^\/api\/orders\/(\d+)$/);
  if (orderMatch && request.method === "GET") {
    const user = userFromRequest(request);
    if (!user) {
      return json({ error: "Нэвтрэх шаардлагатай" }, 401);
    }

    const order = db.orders.find((candidate) => candidate.id === Number(orderMatch[1]));

    // Бусдын захиалгад 403 биш 404 буцаана: «байгаа ч чамд хамаагүй» гэж
    // хэлэх нь тухайн захиалга оршин байгааг илчилнэ.
    if (!order || order.userId !== user.id) {
      return json({ error: "Захиалга олдсонгүй" }, 404);
    }

    return json(order);
  }

  // энд бичнэ үү

  return json({ error: "Хаяг олдсонгүй: " + path }, 404);
}

window.handleRequest = handleRequest;

// «API турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
// Нэвтэрсний дараа ирсэн token-ыг санаж, дараагийн хүсэлтүүдэд хавсаргана.

const db = {
  products: [
    { id: 1, name: "Монгол дээл", price: 129000 },
    { id: 2, name: "Малгай", price: 45000 },
  ],
  // Захиалга бүр ХЭНИЙХ болохыг заана — эрхийн шалгалтын түлхүүр нь энэ.
  orders: [
    { id: 1, userId: 1, items: [{ id: 1, quantity: 1 }] },
    { id: 2, userId: 2, items: [{ id: 2, quantity: 3 }] },
  ],
  users: [],
  sessions: {},
};

window.db = db;

const SCENARIOS = [
  {
    "key": "regOk",
    "label": "Шинэ хэрэглэгч бүртгэх",
    "method": "POST",
    "path": "/api/register",
    "body": {
      "name": "Батаа",
      "email": "bataa@shop.mn",
      "password": "нууц-үг-12345"
    }
  },
  {
    "key": "loginOk",
    "label": "Зөв нууц үгээр нэвтрэх",
    "method": "POST",
    "path": "/api/login",
    "body": {
      "email": "bataa@shop.mn",
      "password": "нууц-үг-12345"
    }
  },
  {
    "key": "meOk",
    "label": "Нэвтэрсэн хэрэглэгч",
    "method": "GET",
    "path": "/api/me",
    "auth": true
  },
  {
    "key": "logout",
    "label": "Гарах",
    "method": "POST",
    "path": "/api/logout",
    "auth": true
  },
  {
    "key": "meAfterLogout",
    "label": "Гарсны дараа өөрийгөө асуух",
    "method": "GET",
    "path": "/api/me",
    "auth": true
  }
];

const output = document.getElementById("output");

function render(scenario, status, body, error, sentToken) {
  const box = document.createElement("section");
  box.className = "call";
  box.dataset.testid = "call-" + scenario.key;

  const head = document.createElement("h2");
  const badge = document.createElement("span");
  badge.className = "status " + (error ? "s-err" : "s-" + String(status)[0] + "xx");
  badge.dataset.testid = "status-" + scenario.key;
  badge.textContent = error ? "алдаа" : String(status);
  head.append(badge, document.createTextNode(" " + scenario.method + " " + scenario.path));
  if (sentToken) {
    const lock = document.createElement("span");
    lock.className = "lock";
    lock.textContent = "🔑 token-той";
    head.append(lock);
  }
  box.append(head);

  const label = document.createElement("p");
  label.className = "muted";
  label.textContent = scenario.label;
  box.append(label);

  const pre = document.createElement("pre");
  pre.dataset.testid = "body-" + scenario.key;
  pre.textContent = error ? error : JSON.stringify(body, null, 2);
  box.append(pre);

  output.append(box);
}

(async function () {
  window.RESULTS = {};
  let token = null;

  for (const scenario of SCENARIOS) {
    const headers = {};
    const init = { method: scenario.method };

    if (scenario.body !== undefined) {
      headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(scenario.body);
    }

    const sendToken = scenario.auth === true && token !== null;
    if (sendToken) headers.Authorization = "Bearer " + token;
    if (scenario.auth === "bad") headers.Authorization = "Bearer not-a-real-token";

    init.headers = headers;

    let status = 0;
    let body = null;
    let error = null;

    try {
      const response = await handleRequest(new Request("https://shop.mn" + scenario.path, init));

      if (!(response instanceof Response)) {
        throw new Error("handleRequest нь Response биш зүйл буцаалаа");
      }

      status = response.status;
      const text = await response.text();
      try {
        body = text ? JSON.parse(text) : null;
      } catch (problem) {
        body = text;
      }

      if (body && typeof body.token === "string") token = body.token;
    } catch (problem) {
      error = problem.message;
    }

    window.RESULTS[scenario.key] = { status, body, error };
    render(scenario, status, body, error, sendToken);
  }

  window.TOKEN = token;
  document.body.dataset.ready = "1";
})();

